const UpsertFeishuAppConfig = `-- name: UpsertFeishuAppConfig :one
INSERT INTO feishu_app_configs (
    tenant_id,
    app_id,
    app_secret_sealed,
    status
) VALUES (
    $1::uuid,
    $2::varchar,
    $3::text,
    COALESCE($4::varchar, 'active')
)
ON CONFLICT (tenant_id, app_id) DO UPDATE SET
    app_secret_sealed = EXCLUDED.app_secret_sealed,
    status = EXCLUDED.status,
    updated_at = NOW()
RETURNING id, tenant_id, app_id, app_secret_sealed, status, created_at, updated_at
`

type UpsertFeishuAppConfigParams struct {
	TenantID        uuid.UUID   `json:"tenant_id"`
	AppID           string      `json:"app_id"`
	AppSecretSealed string      `json:"app_secret_sealed"`
	Status          pgtype.Text `json:"status"`
}

func (q *Queries) UpsertFeishuAppConfig(ctx context.Context, arg UpsertFeishuAppConfigParams) (FeishuAppConfig, error) {
	row := q.db.QueryRow(ctx, UpsertFeishuAppConfig,
		arg.TenantID,
		arg.AppID,
		arg.AppSecretSealed,
		arg.Status,
	)
	var i FeishuAppConfig
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.AppID,
		&i.AppSecretSealed,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}
